  --font-serif: var(--font-serif);
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);

  --shadow-2xs: var(--shadow-2xs);
  --shadow-xs: var(--shadow-xs);
  --shadow-sm: var(--shadow-sm);
  --shadow: var(--shadow);
  --shadow-md: var(--shadow-md);
  --shadow-lg: var(--shadow-lg);
  --shadow-xl: var(--shadow-xl);
  --shadow-2xl: var(--shadow-2xl);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background font-arabic text-foreground;
  }
}

.callout {
  padding: 1rem 1.25rem;
  margin: 1rem 0;
  padding-bottom: 2rem;
  border-radius: var(--radius-lg);
  border-inline-start: 4px solid var(--border);
  background: var(--accent);
}

.callout-title {
  font-family: var(--font-arabic);
  font-weight: 700;
  font-size: 0.875rem;
  margin-bottom: 0.5rem;
}

.callout-quran-ayah {
  border-color: var(--primary);
  background: var(--chart-2);
}

.callout-hadith {
  border-color: var(--primary);
  background: var(--card);
}

.callout-info {
  border-color: oklch(0.5 0.15 250);
  background: oklch(0.96 0.02 250 / 0.3);
}

.callout-warning {
  border-color: oklch(0.7 0.18 85);
  background: oklch(0.97 0.02 85 / 0.3);
}

.callout-error {
  border-color: oklch(0.6 0.2 25);
  background: oklch(0.96 0.02 25 / 0.3);
}

